"""Run a frozen contemporaneous DeepSeek High G* versus FS12 joint comparison.

Both conditions annotate entities and relations in one response.  G* receives
the complete entity and relation guideline artifacts.  FS12 receives the same
12 pilot gold graphs and ordering used in the frozen two-stage few-shot study,
but no generated guideline.  The two conditions are interleaved document by
document over the fixed 38-report evaluation set.

Provider response envelopes and parser outputs remain immutable.  The runner
also materializes a canonical prediction-only, reference-blind offset repair
and reports scores for both views; the normalized view is the headline view.
"""

from __future__ import annotations

import argparse
import copy
import json
import platform
import statistics
import sys
import time
from collections import Counter
from concurrent.futures import ThreadPoolExecutor
from datetime import datetime, timezone
from importlib.metadata import version as package_version
from pathlib import Path

import psutil


ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "scripts"))

import analyze_exact_overlap_gap as offset_repair
import run_deepseek_fewshot_budget as fewshot
import run_heldout38 as held


DEFAULT_PLAN = ROOT / "llm_preliminary/deepseek_high_joint_gstar_fs12_plan.json"
DEFAULT_GOLD = fewshot.DEFAULT_GOLD
DEFAULT_ENTITY_GSTAR = fewshot.DEFAULT_ENTITY_GSTAR
DEFAULT_RELATION_GSTAR = fewshot.DEFAULT_RELATION_GSTAR


def cli() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument("--env-file", type=Path, required=True)
    parser.add_argument("--plan", type=Path, default=DEFAULT_PLAN)
    parser.add_argument("--gold", type=Path, default=DEFAULT_GOLD)
    parser.add_argument("--entity-gstar", type=Path, default=DEFAULT_ENTITY_GSTAR)
    parser.add_argument("--relation-gstar", type=Path, default=DEFAULT_RELATION_GSTAR)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--workers", type=int, default=8)
    parser.add_argument("--max-retries", type=int, default=8)
    parser.add_argument("--prepare-only", action="store_true")
    parser.add_argument("--resume", action="store_true")
    return parser.parse_args()


def joint_demonstration(row: dict) -> dict:
    return {
        "report": {"doc_id": str(row["doc_id"]), "text": row["text"]},
        "offset_reference": held.base.indexed_text(row["text"]),
        "gold_output": {
            "entities": copy.deepcopy(row["entities"]),
            "relations": copy.deepcopy(row["relations"]),
        },
    }


def combined_guidance(entity_path: Path, relation_path: Path) -> str:
    return (
        "ENTITY GUIDELINES\n"
        + held.guideline_text(entity_path, "entity")
        + "\n\nRELATION GUIDELINES\n"
        + held.guideline_text(relation_path, "relation")
    )


def build_conditions(plan: dict, pilot_by_id: dict[str, dict], entity_path: Path, relation_path: Path) -> dict:
    conditions = {}
    full_guidance = combined_guidance(entity_path, relation_path)
    for condition_id, specification in plan["conditions"].items():
        demo_ids = [str(doc_id) for doc_id in specification["demonstration_doc_ids"]]
        missing = [doc_id for doc_id in demo_ids if doc_id not in pilot_by_id]
        if missing:
            raise ValueError(f"Unknown pilot demonstration IDs for {condition_id}: {missing}")
        is_guideline = specification["type"] == "combined_guideline"
        conditions[condition_id] = {
            "type": specification["type"],
            "demo_ids": demo_ids,
            "guidance": full_guidance if is_guideline else "No additional annotation guideline is provided.",
            "demonstrations": [joint_demonstration(pilot_by_id[doc_id]) for doc_id in demo_ids],
        }
    return conditions


def joint_payload(target: dict, condition: dict) -> dict:
    return {
        "task_schema": held.ENTITY_SCHEMA + "\n\n" + held.RELATION_SCHEMA,
        "operational_guidance": condition["guidance"],
        "demonstration_instruction": (
            "Demonstrations, when present, are complete annotated pilot graphs. "
            "Infer task conventions from them, but annotate only target_report. "
            "Entity IDs in each relation must reference entities returned for that same report."
        ),
        "demonstrations": condition["demonstrations"],
        "target_report": {"doc_id": str(target["doc_id"]), "text": target["text"]},
        "target_offset_reference": held.base.indexed_text(target["text"]),
        "output_contract": {
            "type": "object",
            "required": ["entities", "relations"],
            "entities": {
                "type": "array",
                "item_required": ["id", "start", "end", "label", "text"],
                "constraints": [
                    "id is unique",
                    "start and end are integer half-open offsets into target_report.text",
                    "text equals target_report.text[start:end]",
                    "label is one of ANAT, OBS-DP, OBS-DA, OBS-U",
                ],
            },
            "relations": {
                "type": "array",
                "item_required": ["subj", "pred", "obj"],
                "constraints": [
                    "subj and obj reference IDs in the returned entities array",
                    "pred is one of Modify, LocatedAt, SuggestiveOf",
                    "the ordered triple is unique",
                ],
            },
        },
    }


def raw_mismatch_details(target: dict, answer: dict) -> list[dict]:
    details = []
    proposed = answer.get("entities", [])
    if not isinstance(proposed, list):
        return details
    seen = set()
    for item in proposed:
        if not isinstance(item, dict):
            continue
        try:
            start, end, label = int(item["start"]), int(item["end"]), str(item["label"])
        except (KeyError, TypeError, ValueError):
            continue
        key = (start, end, label)
        if label not in held.two.ENTITY_LABELS or not 0 <= start < end <= len(target["text"]) or key in seen:
            continue
        seen.add(key)
        returned_text = item.get("text")
        offset_text = target["text"][start:end]
        if returned_text != offset_text:
            details.append(
                {
                    "doc_id": str(target["doc_id"]),
                    "start": start,
                    "end": end,
                    "label": label,
                    "returned_text": returned_text,
                    "offset_text": offset_text,
                }
            )
    return details


def parse_joint(target: dict, answer: dict) -> tuple[dict, dict, list[dict]]:
    entities, entity_audit = held.normalize_entities_audit(target, answer)
    triple_to_new = {(entity["start"], entity["end"], entity["label"]): entity["id"] for entity in entities}
    old_to_new = {}
    proposed_entities = answer.get("entities", [])
    if isinstance(proposed_entities, list):
        for item in proposed_entities:
            if not isinstance(item, dict):
                continue
            try:
                old_to_new[str(item.get("id"))] = triple_to_new[
                    (int(item["start"]), int(item["end"]), str(item["label"]))
                ]
            except (KeyError, TypeError, ValueError):
                pass
    proposed_relations = answer.get("relations", [])
    if not isinstance(proposed_relations, list):
        proposed_relations = []
    mapped = {
        "relations": [
            {
                "subj": old_to_new.get(str(relation.get("subj")), ""),
                "pred": relation.get("pred"),
                "obj": old_to_new.get(str(relation.get("obj")), ""),
            }
            for relation in proposed_relations
            if isinstance(relation, dict)
        ]
    }
    relations, relation_audit = held.normalize_relations_audit(mapped, {entity["id"] for entity in entities})
    prediction = {
        "doc_id": target["doc_id"],
        "split": "heldout",
        "text": target["text"],
        "entities": entities,
        "relations": relations,
    }
    return prediction, {"entity": entity_audit, "relation": relation_audit}, raw_mismatch_details(target, answer)


def validate_demonstration(demonstration: dict) -> None:
    text = demonstration["report"]["text"]
    entities = demonstration["gold_output"]["entities"]
    entity_ids = {str(entity["id"]) for entity in entities}
    if len(entity_ids) != len(entities):
        raise ValueError(f"Duplicate demonstration entity IDs: {demonstration['report']['doc_id']}")
    for entity in entities:
        start, end = int(entity["start"]), int(entity["end"])
        if not 0 <= start < end <= len(text) or text[start:end] != entity["text"]:
            raise ValueError(f"Invalid demonstration entity: {demonstration['report']['doc_id']} {entity}")
    for relation in demonstration["gold_output"]["relations"]:
        if str(relation["subj"]) not in entity_ids or str(relation["obj"]) not in entity_ids:
            raise ValueError(f"Invalid demonstration relation endpoint: {demonstration['report']['doc_id']} {relation}")


def prompt_preflight(conditions: dict, targets: list[dict], pilot_ids: set[str]) -> dict:
    target_ids = {str(target["doc_id"]) for target in targets}
    if target_ids.intersection(pilot_ids):
        raise ValueError("Pilot/evaluation document ID overlap")
    rows = []
    for condition_id, condition in conditions.items():
        for demonstration in condition["demonstrations"]:
            validate_demonstration(demonstration)
        payload_lengths = [len(json.dumps(joint_payload(target, condition), ensure_ascii=False)) for target in targets]
        rows.append(
            {
                "condition": condition_id,
                "demonstration_reports": len(condition["demo_ids"]),
                "demonstration_doc_ids": condition["demo_ids"],
                "joint_prompt_characters_mean": statistics.mean(payload_lengths),
                "joint_prompt_characters_max": max(payload_lengths),
                "guidance_characters": len(condition["guidance"]),
            }
        )
    if set(conditions) != {"Gstar_joint_current", "FS12_joint_direct_gold"}:
        raise ValueError("Frozen protocol requires exactly Gstar_joint_current and FS12_joint_direct_gold")
    if len(conditions["FS12_joint_direct_gold"]["demo_ids"]) != 12:
        raise ValueError("FS12 condition must contain all 12 pilot demonstrations")
    if conditions["Gstar_joint_current"]["demo_ids"]:
        raise ValueError("G* condition must not contain demonstrations")
    return {
        "status": "PASS",
        "evaluation_reports": len(targets),
        "planned_provider_calls": len(targets) * len(conditions),
        "evaluation_gold_in_prompt": False,
        "pilot_evaluation_doc_id_overlap": False,
        "demonstration_graph_integrity": "PASS",
        "conditions": rows,
    }


def annotate_joint(api, conditions: dict, targets: list[dict], root: Path, workers: int) -> tuple[dict, dict]:
    system = (
        "Annotate entities and directed relations jointly in target_report. Return one valid JSON object and no "
        "explanation. Relation endpoints must reference entity IDs in the same response."
    )
    tasks = held.cyclic_tasks(targets, list(conditions))

    def one(task):
        condition_id, target = task
        condition = conditions[condition_id]
        payload = joint_payload(target, condition)
        output = root / condition_id
        held.dump(output / "joint_prompts" / f"{target['doc_id']}.json", {"system": system, "user": payload})
        answer = api.json(
            system,
            payload,
            output / "raw_joint" / f"{target['doc_id']}.json",
            {
                "phase": "joint",
                "condition": condition_id,
                "doc_id": str(target["doc_id"]),
                "demonstration_reports": len(condition["demo_ids"]),
            },
        )
        prediction, audit, mismatches = parse_joint(target, answer)
        return condition_id, prediction, audit, mismatches

    grouped = {condition_id: [] for condition_id in conditions}
    audits = {condition_id: {} for condition_id in conditions}
    mismatches = {condition_id: [] for condition_id in conditions}
    with ThreadPoolExecutor(max_workers=workers) as pool:
        for condition_id, prediction, audit, raw_mismatches in pool.map(one, tasks):
            grouped[condition_id].append(prediction)
            audits[condition_id][str(prediction["doc_id"])] = audit
            mismatches[condition_id].extend(raw_mismatches)
    for condition_id in grouped:
        grouped[condition_id].sort(key=lambda row: str(row["doc_id"]))
        output = root / condition_id
        held.dump(output / "predictions_parser_view.json", grouped[condition_id])
        held.dump(output / "validation.json", audits[condition_id])
        held.dump(output / "raw_text_offset_mismatches.json", mismatches[condition_id])
    return grouped, mismatches


def normalize_predictions(grouped: dict, mismatches: dict, root: Path) -> tuple[dict, dict]:
    normalized = {}
    repair_audits = {}
    for condition_id, rows in grouped.items():
        normalized_rows, repair_audit = offset_repair.local_raw_text_repair(rows, mismatches[condition_id])
        normalized[condition_id] = normalized_rows
        repair_audits[condition_id] = repair_audit
        output = root / condition_id
        held.dump(output / "predictions.json", normalized_rows)
        held.dump(output / "offset_repair_audit.json", repair_audit)
    return normalized, repair_audits


def score_view(gold: list[dict], predictions: dict) -> tuple[dict, dict]:
    results = {}
    counts = {}
    for condition_id, rows in predictions.items():
        entity_score, entity_counts = held.score_docs(gold, rows, "entity")
        relation_score, relation_counts = held.score_docs(gold, rows, "relation")
        results[condition_id] = {"entity": entity_score, "relation": relation_score}
        counts[condition_id] = {"entity": entity_counts, "relation": relation_counts}
    return results, counts


def contrast(results: dict, counts: dict) -> dict:
    first, second = "FS12_joint_direct_gold", "Gstar_joint_current"
    output = {}
    for target_type in ("entity", "relation"):
        bootstrap = held.paired_bootstrap(counts[first][target_type], counts[second][target_type])
        bootstrap["difference"] = results[first][target_type]["f1"] - results[second][target_type]["f1"]
        output[target_type] = bootstrap
    return output


def main() -> None:
    args = cli()
    started_utc = datetime.now(timezone.utc).isoformat()
    wall_tick = time.perf_counter()
    cpu_tick = time.process_time()
    process = psutil.Process()
    initial_rss = process.memory_info().rss

    plan = json.loads(args.plan.read_text(encoding="utf-8"))
    if not args.prepare_only and plan.get("status") != "FROZEN_BEFORE_EXECUTION":
        raise RuntimeError("Execution blocked until plan status is FROZEN_BEFORE_EXECUTION")
    all_rows = fewshot.load_rows(args.gold)
    pilot = [row for row in all_rows if row.get("split") == "pilot"]
    evaluation_gold = sorted(
        [row for row in all_rows if row.get("split") == "heldout"], key=lambda row: str(row["doc_id"])
    )
    if len(pilot) != 12 or len(evaluation_gold) != 38:
        raise ValueError(f"Expected 12 pilot and 38 evaluation reports; found {len(pilot)} and {len(evaluation_gold)}")
    pilot_by_id = {str(row["doc_id"]): row for row in pilot}
    targets = [{"doc_id": row["doc_id"], "text": row["text"]} for row in evaluation_gold]
    conditions = build_conditions(plan, pilot_by_id, args.entity_gstar.resolve(), args.relation_gstar.resolve())
    preflight = prompt_preflight(conditions, targets, set(pilot_by_id))

    existing = list(args.output.iterdir()) if args.output.exists() else []
    if existing and not args.resume:
        raise RuntimeError(f"Output directory is not empty; use a fresh path or --resume: {args.output}")
    args.output.mkdir(parents=True, exist_ok=True)
    frozen = args.output / "frozen_inputs"
    for condition_id, condition in conditions.items():
        condition_root = frozen / condition_id
        held.dump(condition_root / "demonstrations.json", condition["demonstrations"])
        condition_root.mkdir(parents=True, exist_ok=True)
        (condition_root / "guidance.txt").write_text(condition["guidance"] + "\n", encoding="utf-8")
    held.dump(args.output / "preflight_report.json", preflight)
    schedule = [
        {"condition": condition_id, "doc_id": str(target["doc_id"])}
        for condition_id, target in held.cyclic_tasks(targets, list(conditions))
    ]
    held.dump(args.output / "call_schedule.json", {"joint": schedule})

    paths = {"entity_gstar": args.entity_gstar.resolve(), "relation_gstar": args.relation_gstar.resolve()}
    identity = {
        "protocol": plan["protocol"],
        "provider": "deepseek",
        "model": "deepseek-v4-pro",
        "reasoning_effort": "high",
        "plan_sha256": held.sha(args.plan),
        "gold_sha256": held.sha(args.gold),
        "artifact_sha256": {name: held.sha(path) for name, path in paths.items()},
        "runner_sha256": held.sha(Path(__file__)),
    }
    manifest = {
        **identity,
        "status": "PREPARED" if args.prepare_only else "RUNNING",
        "analysis_role": plan["analysis_role"],
        "created_utc": datetime.now(timezone.utc).isoformat(),
        "conditions": list(conditions),
        "workers": args.workers,
        "pilot_reports": 12,
        "evaluation_reports": 38,
        "evaluation_gold_in_api_prompts": False,
        "adaptive_revision_on_evaluation_set": False,
        "run_identity": identity,
        "schedule_sha256": held.sha(args.output / "call_schedule.json"),
        "preflight_sha256": held.sha(args.output / "preflight_report.json"),
        "frozen_input_sha256": {
            str(path.relative_to(args.output)): held.sha(path) for path in sorted(frozen.rglob("*")) if path.is_file()
        },
        "pricing_snapshot": held.PRICING_SNAPSHOT,
        "environment": {
            "python": platform.python_version(),
            "platform": platform.platform(),
            "openai_package": package_version("openai"),
            "psutil_package": package_version("psutil"),
        },
    }
    if args.resume and (args.output / "manifest.json").exists():
        old = json.loads((args.output / "manifest.json").read_text(encoding="utf-8"))
        if old.get("run_identity") != identity:
            raise RuntimeError("Resume rejected: run identity differs from the frozen execution")
    held.dump(args.output / "manifest.json", manifest)
    if args.prepare_only:
        print(json.dumps({"status": "PREPARE_ONLY_OK", "preflight": preflight}, ensure_ascii=False, indent=2))
        return

    held.base.load_env(args.env_file)
    api = held.FrozenAPI("deepseek", "deepseek-v4-pro", "high", args.max_retries, args.resume, args.output)
    timings = {}
    held.dump(args.output / "run_state.json", {"status": "RUNNING", "run_started_utc": started_utc})

    phase_started = datetime.now(timezone.utc).isoformat()
    phase_tick = time.perf_counter()
    try:
        parser_predictions, mismatches = annotate_joint(api, conditions, targets, args.output, args.workers)
    except Exception as error:
        timings["joint"] = {
            "status": "FAILED",
            "started_utc": phase_started,
            "failed_utc": datetime.now(timezone.utc).isoformat(),
            "wall_seconds": time.perf_counter() - phase_tick,
            "error_type": type(error).__name__,
            "error_message": str(error)[:1000],
        }
        held.dump(args.output / "phase_timings.json", timings)
        held.dump(args.output / "run_state.json", {"status": "FAILED", "failed_phase": "joint", "error": str(error)[:1000]})
        raise
    timings["joint"] = {
        "status": "COMPLETED",
        "started_utc": phase_started,
        "completed_utc": datetime.now(timezone.utc).isoformat(),
        "wall_seconds": time.perf_counter() - phase_tick,
    }
    held.dump(args.output / "phase_timings.json", timings)

    normalized_predictions, repair_audits = normalize_predictions(parser_predictions, mismatches, args.output)
    parser_results, parser_counts = score_view(evaluation_gold, parser_predictions)
    normalized_results, normalized_counts = score_view(evaluation_gold, normalized_predictions)
    for condition_id in conditions:
        held.dump(
            args.output / condition_id / "scores.json",
            {"parser_view": parser_results[condition_id], "normalized_view": normalized_results[condition_id]},
        )
    report = {
        "scope": "post-hoc secondary joint-architecture comparison on the fixed 38-report evaluation set",
        "headline_prediction_view": "prediction-only reference-blind offset normalization",
        "parser_view": {"results": parser_results, "contrast_FS12_minus_Gstar": contrast(parser_results, parser_counts)},
        "normalized_view": {
            "results": normalized_results,
            "contrast_FS12_minus_Gstar": contrast(normalized_results, normalized_counts),
        },
        "offset_normalization": {
            condition_id: {
                "raw_text_offset_mismatches": len(mismatches[condition_id]),
                "repaired": sum(row["status"] == "repaired" for row in repair_audits[condition_id]),
                "not_repaired": sum(row["status"] != "repaired" for row in repair_audits[condition_id]),
            }
            for condition_id in conditions
        },
    }
    held.dump(args.output / "results.json", report)

    resources = {
        "run_started_utc": started_utc,
        "run_completed_utc": datetime.now(timezone.utc).isoformat(),
        "total_wall_seconds": time.perf_counter() - wall_tick,
        "total_process_cpu_seconds": time.process_time() - cpu_tick,
        "initial_rss_bytes": initial_rss,
        "final_rss_bytes": process.memory_info().rss,
        "workers": args.workers,
        "max_retries": args.max_retries,
        "phase_timings": timings,
        "ledger": held.ledger_summary(args.output / "call_ledger.jsonl"),
        "validation": held.validation_summary(args.output),
        "pricing_snapshot": held.PRICING_SNAPSHOT,
    }
    resources["output_directory_bytes_before_resource_summary"] = held.directory_bytes(args.output)
    held.dump(args.output / "resource_summary.json", resources)
    resources["output_directory_bytes_final"] = held.directory_bytes(args.output)
    held.dump(args.output / "resource_summary.json", resources)
    fingerprints = sorted(
        {str(event.get("system_fingerprint")) for event in api.usage if event.get("system_fingerprint")}
    )
    manifest.update(
        {
            "status": "COMPLETED",
            "completed_utc": resources["run_completed_utc"],
            "system_fingerprints": fingerprints,
            "results": normalized_results,
            "resource_summary": "resource_summary.json",
            "call_ledger": "call_ledger.jsonl",
        }
    )
    held.dump(args.output / "manifest.json", manifest)
    held.dump(
        args.output / "run_state.json",
        {"status": "COMPLETED", "completed_utc": resources["run_completed_utc"], "completed_phases": ["joint"]},
    )
    print(json.dumps(report, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()
